lessons.solution:
class Conta:
    def __init__(self, titular):
        self.titular = titular
        self.saldo = 0

    def depositar(self, valor):
        self.saldo += valor

    def sacar(self, valor):
        if valor > self.saldo:
            return False
        self.saldo -= valor
        return True


n = int(input())
contas = {}
for i in range(n):
    operacao, nome, texto = input().split()
    valor = int(texto)
    if nome not in contas:
        contas[nome] = Conta(nome)
    conta = contas[nome]
    if operacao == "deposito":
        conta.depositar(valor)
    elif not conta.sacar(valor):
        print(f"Saldo insuficiente: {nome}")
for nome in sorted(contas):
    print(f"{nome}: {contas[nome].saldo}")

def intercalar(a, b):
    r = []
    i = 0
    j = 0
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            r.append(a[i])
            i += 1
        else:
            r.append(b[j])
            j += 1
    return r + a[i:] + b[j:]


def merge_sort(v):
    if len(v) <= 1:
        return v
    meio = len(v) // 2
    return intercalar(merge_sort(v[:meio]), merge_sort(v[meio:]))


def busca(v, alvo):
    ini = 0
    fim = len(v)
    while ini < fim:
        meio = (ini + fim) // 2
        if v[meio] < alvo:
            ini = meio + 1
        else:
            fim = meio
    if ini < len(v) and v[ini] == alvo:
        return ini
    return -1


n = int(input())
v = [int(x) for x in input().split()]
q = int(input())
ordenada = merge_sort(v)
if ordenada:
    print("Ordenada: " + " ".join(str(x) for x in ordenada))
else:
    print("Ordenada: vazia")
for k in range(q):
    alvo = int(input())
    pos = busca(ordenada, alvo)
    if pos >= 0:
        print(f"{alvo}: posição {pos}")
    else:
        print(f"{alvo}: não encontrado")
